1	import Foundation
2	
3	/// Holds the cleanup LLM to the edits dictation cleanup exists for. The
4	/// model's output is aligned word by word against the transcript it was
5	/// given, and only these edits survive:
6	///  - deleting filler sounds (um, uh, er, hmm, …), and "you know" / "I mean" /
7	///    "like" when the transcript sets them off with commas;
8	///  - deleting stutters (a word or phrase said twice back to back);
9	///  - deleting a self-corrected span that ends in a correction cue
10	///    ("at 2, no wait, 3" → "at 3"; "to Bob, sorry, I mean to Alice" → "to Alice");
11	///  - re-spacing or re-hyphenating the same letters ("fine tune" → "fine-tune");
12	///  - replacing a short span with a vocabulary term it resembles ("pie torch" → "PyTorch").
13	/// Every other change (a dropped clause, a paraphrase, an added word, an
14	/// answer to a dictated question) is reverted to the transcript's own words,
15	/// so the speaker's sentences come through as spoken. Measured on a 44-case
16	/// fidelity corpus, unguarded Llama-3.2-3B rewrote 10 of 22 sentences that
17	/// needed no edit (36 words lost), answered "Tell me a joke about databases"
18	/// with a joke, and obeyed a dictated "reply with the word banana".
19	///
20	/// Pure and deterministic; the output is exactly the model's text whenever
21	/// the model made only allowed edits.
22	public enum CleanupGuard {
23	    static let fillers: Set<String> = [
24	        "um", "umm", "uh", "uhh", "uhm", "er", "erm", "ah", "eh", "hmm", "hm", "mm", "mmm", "mhm",
25	    ]
26	    /// Deletable only when the transcript brackets them with commas on both
27	    /// sides ("I was, you know, thinking"): otherwise they are usually content.
28	    static let bracketedFillers: [[String]] = [["you", "know"], ["i", "mean"], ["like"]]
29	    /// A deleted run counts as a self-correction only if it ends in one of
30	    /// these (plus at most `maxTokensAfterCue` words) and has words before it.
31	    static let correctionCues: [[String]] = [
32	        ["no", "wait"], ["wait"], ["sorry"], ["i", "mean"], ["i", "meant"], ["actually"],
33	        ["make", "that"], ["scratch", "that"], ["or", "rather"], ["rather"], ["correction"], ["no"],
34	    ]
35	    /// Alignment is O(n·m): ~2,000 words a side (13+ minutes of speech, past
36	    /// `maxRecordSeconds`) before the guard stops aligning and keeps the
37	    /// transcript as spoken.
38	    static let maxAlignmentCells = 4_000_000
39	    static let maxCorrectionRun = 12
40	    static let maxTokensAfterCue = 2
41	    static let maxSubstitutionTokens = 4
42	    /// Letter similarity a span needs to be swapped for a vocabulary term:
43	    /// low enough for phonetic misses ("pie torch" → PyTorch, 0.75), high
44	    /// enough to refuse unrelated words.
45	    static let minVocabularySimilarity = 0.5
46	    /// Number words align with digits, so a correction the model wrote as
47	    /// "3 pm" still lines up with a spoken "three pm".
48	    static let numberWords: [String: String] = [
49	        "zero": "0", "one": "1", "two": "2", "three": "3", "four": "4", "five": "5",
50	        "six": "6", "seven": "7", "eight": "8", "nine": "9", "ten": "10", "eleven": "11",
51	        "twelve": "12", "thirteen": "13", "fourteen": "14", "fifteen": "15", "sixteen": "16",
52	        "seventeen": "17", "eighteen": "18", "nineteen": "19", "twenty": "20", "thirty": "30",
53	        "forty": "40", "fifty": "50", "sixty": "60", "seventy": "70", "eighty": "80", "ninety": "90",
54	    ]
55	
56	    /// Lookup keys for `reconcile`'s vocabulary check; build once per term list.
57	    public static func vocabularyKeys(_ terms: [String]) -> Set<String> {
58	        Set(VocabularyPrompt.normalize(terms).map(TranscriptCorrector.key))
59	    }
60	
61	    /// `vocabularyKeys` comes from `vocabularyKeys(_:)`.
62	    public static func reconcile(transcript: String, cleaned: String,
63	                                 vocabularyKeys: Set<String>) -> String {
64	        let input = tokenize(transcript)
65	        let output = tokenize(cleaned)
66	        let a = input.indices.filter { !input[$0].key.isEmpty }
67	        let b = output.indices.filter { !output[$0].key.isEmpty }
68	        guard !a.isEmpty, !b.isEmpty, a.count * b.count <= maxAlignmentCells else { return transcript }
69	
70	        // 1. Decide the fate of every word in the transcript.
71	        var fate = [Fate](repeating: .restored, count: input.count)
72	        var revertedBoundary = Set<Int>() // input indices next to a dropped insertion
73	        var reverted = false
74	        let ops = align(a.map { input[$0].matchKey }, b.map { output[$0].matchKey })
75	        var k = 0
76	        var lastMatched = -1 // position in `a` of the latest aligned word
77	        while k < ops.count {
78	            if case .match(let ai, let bi) = ops[k] {
79	                fate[a[ai]] = .matched(b[bi])
80	                lastMatched = ai
81	                k += 1
82	                continue
83	            }
84	            var deleted: [Int] = [] // positions in `a`
85	            var inserted: [Int] = [] // positions in `b`
86	            while k < ops.count {
87	                if case .delete(let ai) = ops[k] { deleted.append(ai) } else if case .insert(let bi) = ops[k] {
88	                    inserted.append(bi)
89	                } else { break }
90	                k += 1
91	            }
92	            let matchAfter = k < ops.count
93	            let substitution = inserted.isEmpty ? nil
94	                : bestSubstitution(deleted.map { input[a[$0]] }, inserted.map { output[b[$0]] },
95	                                   vocabularyKeys: vocabularyKeys)
96	            if let s = substitution {
97	                let span = deleted[s]
98	                let surfaces = inserted.map { output[b[$0]].surface }
99	                fate[a[span[span.startIndex]]] = .substitutedHead(surfaces, last: a[span[span.endIndex - 1]])
100	                for ai in span.dropFirst() { fate[a[ai]] = .substitutedTail }
101	                judgeDeletion(Array(deleted[..<s.lowerBound]), keptAfter: true,
102	                              input: input, a: a, fate: &fate)
103	                judgeDeletion(Array(deleted[s.upperBound...]), keptAfter: matchAfter,
104	                              input: input, a: a, fate: &fate)
105	            } else {
106	                judgeDeletion(deleted, keptAfter: matchAfter, input: input, a: a, fate: &fate)
107	                if !inserted.isEmpty {
108	                    // Dropped model words: the aligned words on both sides of
109	                    // the gap were written around them.
110	                    reverted = true
111	                    if lastMatched >= 0 { revertedBoundary.insert(a[lastMatched]) }
112	                    let after = lastMatched + deleted.count + 1
113	                    if after < a.count { revertedBoundary.insert(a[after]) }
114	                }
115	            }
116	        }
117	        if a.contains(where: { if case .restored = fate[$0] { return true } else { return false } }) {
118	            reverted = true
119	        }
120	        // The model made only allowed edits: its text stands exactly as written.
121	        guard reverted else { return cleaned }
122	
123	        // 2. Rebuild from the transcript. Words beside a reverted edit take the
124	        // transcript's spelling and punctuation: the model's there was written
125	        // for a sentence that no longer exists ("…to Thursday." before a
126	        // restored "because…" clause).
127	        var pieces: [Piece] = []
128	        var pendingDeletion: Int?  // first index of the deletion run awaiting its neighbor
129	        var lastWasKept = false
130	        for i in input.indices {
131	            switch fate[i] {
132	            case .matched(let bi):
133	                pieces.append(Piece(surface: output[bi].surface, first: i, input: i, kind: .matched,
134	                                    deletedBefore: pendingDeletion))
135	            case .restored:
136	                if input[i].key.isEmpty {
137	                    guard lastWasKept else { continue } // dangling punctuation of a deletion
138	                }
139	                pieces.append(Piece(surface: input[i].surface, first: i, input: i, kind: .restored,
140	                                    deletedBefore: pendingDeletion))
141	            case .substitutedHead(let surfaces, let last):
142	                pieces.append(Piece(surface: surfaces.joined(separator: " "), first: i, input: last,
143	                                    kind: .substituted, deletedBefore: pendingDeletion))
144	            case .substitutedTail:
145	                continue
146	            case .deleted:
147	                if pendingDeletion == nil { pendingDeletion = i }
148	                lastWasKept = false
149	                continue
150	            }
151	            pendingDeletion = nil
152	            lastWasKept = true
153	        }
154	        let trailingDeletion = pendingDeletion
155	        guard !pieces.isEmpty else { return transcript }
156	
157	        func usesTranscriptSurface(_ p: Int) -> Bool {
158	            switch pieces[p].kind {
159	            case .restored: return true
160	            case .substituted: return false
161	            case .matched:
162	                if revertedBoundary.contains(pieces[p].input) { return true }
163	                if p > 0, pieces[p - 1].kind == .restored { return true }
164	                if p + 1 < pieces.count, pieces[p + 1].kind == .restored { return true }
165	                return false
166	            }
167	        }
168	        var surfaces: [String] = []
169	        var transcriptSurface: [Bool] = []
170	        for p in pieces.indices {
171	            let own = usesTranscriptSurface(p)
172	            transcriptSurface.append(own)
173	            switch pieces[p].kind {
174	            case .matched where own:
175	                surfaces.append(input[pieces[p].input].surface)
176	            case .substituted where p + 1 < pieces.count && pieces[p + 1].kind == .restored:
177	                // Keep the transcript's punctuation after a swapped-in term.
178	                surfaces.append(stripTrailingPunctuation(pieces[p].surface)
179	                                + trailingPunctuation(input[pieces[p].input].surface))
180	            default:
181	                surfaces.append(pieces[p].surface)
182	            }
183	        }
184	
185	        // 3. Seam repair where an allowed deletion meets transcript-spelled words.
186	        for p in pieces.indices {
187	            guard let start = pieces[p].deletedBefore else { continue }
188	            let lastDeleted = lastWordIndex(input, from: start, before: pieces[p].first)
189	            if p > 0, transcriptSurface[p - 1], surfaces[p - 1].hasSuffix(","),
190	               let last = lastDeleted, input[last].surface.hasSuffix(",") {
191	                surfaces[p - 1].removeLast() // "which is, um, way" → "which is way"
192	            }
193	            let atSentenceStart = p == 0 || endsSentence(surfaces[p - 1])
194	            if atSentenceStart, transcriptSurface[p], startsUppercase(input[start].surface) {
195	                surfaces[p] = sentenceCased(surfaces[p], vocabularyKeys) // "Hmm, let me" → "Let me"
196	            }
197	        }
198	        // The model capitalized the opening word: keep that even where the
199	        // transcript's own (lowercase) first word came back.
200	        if transcriptSurface[0], output[b[0]].surface.first(where: \.isLetter)?.isUppercase == true {
201	            surfaces[0] = sentenceCased(surfaces[0], vocabularyKeys)
202	        }
203	        if let start = trailingDeletion, let lastIdx = surfaces.indices.last, transcriptSurface[lastIdx],
204	           !endsSentence(surfaces[lastIdx]),
205	           let last = lastWordIndex(input, from: start, before: input.count) {
206	            let terminal = trailingPunctuation(input[last].surface).filter { ".?!".contains($0) }
207	            if !terminal.isEmpty {
208	                surfaces[lastIdx] = stripTrailingPunctuation(surfaces[lastIdx]) + terminal // "I think, um." → "I think."
209	            }
210	        }
211	        return surfaces.joined(separator: " ")
212	    }
213	
214	    // MARK: tokens and alignment
215	
216	    struct Token {
217	        let surface: String
218	        let key: String      // letters+digits, lowercased; "" for punctuation-only
219	        let matchKey: String // key with number words as digits
220	    }
221	
222	    static func tokenize(_ text: String) -> [Token] {
223	        text.split(whereSeparator: \.isWhitespace).map { raw in
224	            let surface = String(raw)
225	            let key = TranscriptCorrector.key(surface)
226	            return Token(surface: surface, key: key, matchKey: numberWords[key] ?? key)
227	        }
228	    }
229	
230	    enum Op: Equatable { case match(Int, Int), delete(Int), insert(Int) }
231	
232	    /// Longest-common-subsequence alignment, backtracked from the END so a
233	    /// repeated word pairs with its LAST occurrence: the kept half of a
234	    /// stutter or a self-correction is the one spoken later.
235	    static func align(_ x: [String], _ y: [String]) -> [Op] {
236	        let n = x.count, m = y.count
237	        let width = m + 1
238	        var dp = [Int32](repeating: 0, count: (n + 1) * width)
239	        for i in stride(from: 1, through: n, by: 1) {
240	            for j in stride(from: 1, through: m, by: 1) {
241	                dp[i * width + j] = x[i - 1] == y[j - 1]
242	                    ? dp[(i - 1) * width + j - 1] + 1
243	                    : max(dp[(i - 1) * width + j], dp[i * width + j - 1])
244	            }
245	        }
246	        var ops: [Op] = []
247	        var i = n, j = m
248	        while i > 0 || j > 0 {
249	            if i > 0, j > 0, x[i - 1] == y[j - 1] {
250	                ops.append(.match(i - 1, j - 1)); i -= 1; j -= 1
251	            } else if i > 0, j == 0 || dp[(i - 1) * width + j] >= dp[i * width + j - 1] {
252	                ops.append(.delete(i - 1)); i -= 1
253	            } else {
254	                ops.append(.insert(j - 1)); j -= 1
255	            }
256	        }
257	        return ops.reversed()
258	    }
259	
260	    // MARK: edit rules
261	
262	    enum Fate {
263	        case matched(Int)            // output token index
264	        case restored                // transcript word the model dropped without cause
265	        case deleted                 // an allowed deletion
266	        case substitutedHead([String], last: Int) // output surfaces; last transcript index
267	        case substitutedTail
268	    }
269	
270	    enum PieceKind { case matched, restored, substituted }
271	
272	    struct Piece {
273	        let surface: String
274	        let first: Int          // first transcript index covered
275	        let input: Int          // last transcript index covered
276	        let kind: PieceKind
277	        let deletedBefore: Int? // start of an allowed deletion right before this piece
278	    }
279	
280	    /// Marks the allowed deletions in a run of dropped transcript words
281	    /// (positions in `a`); everything else stays `.restored`.
282	    static func judgeDeletion(_ run: [Int], keptAfter: Bool, input: [Token], a: [Int],
283	                              fate: inout [Fate]) {
284	        guard !run.isEmpty else { return }
285	        let keys = run.map { input[a[$0]].key }
286	        let wholeRun = isCorrection(keys, keptAfter: keptAfter)
287	            || isRepeat(run, input: input, a: a)
288	            || isBracketedFiller(run, keys: keys, input: input, a: a)
289	        for (offset, ai) in run.enumerated() {
290	            let key = keys[offset]
291	            if wholeRun || fillers.contains(key) || isStutter(ai, run: run, input: input, a: a) {
292	                fate[a[ai]] = .deleted
293	            }
294	        }
295	    }
296	
297	    /// The same word said again right beside it, fillers aside ("the, uh, the
298	    /// link"), where that other copy is outside this run: dropping both copies
299	    /// would lose the word.
300	    static func isStutter(_ ai: Int, run: [Int], input: [Token], a: [Int]) -> Bool {
301	        let key = input[a[ai]].key
302	        for step in [-1, 1] {
303	            var j = ai + step
304	            while j >= 0, j < a.count, fillers.contains(input[a[j]].key) { j += step }
305	            if j >= 0, j < a.count, !run.contains(j), input[a[j]].key == key { return true }
306	        }
307	        return false
308	    }
309	
310	    /// "<words> <cue> [≤2 words]" with a replacement still to come: the
311	    /// corrected words, then the cue, e.g. "2, no wait," or "Bob, sorry, I mean".
312	    static func isCorrection(_ keys: [String], keptAfter: Bool) -> Bool {
313	        guard keptAfter, keys.count >= 2, keys.count <= maxCorrectionRun else { return false }
314	        var covered = [Bool](repeating: false, count: keys.count)
315	        var last: Range<Int>? // the cue ending latest (longest on ties)
316	        for start in keys.indices {
317	            for cue in correctionCues where start + cue.count <= keys.count
318	                && Array(keys[start..<start + cue.count]) == cue {
319	                for i in start..<start + cue.count { covered[i] = true }
320	                let range = start..<start + cue.count
321	                if last == nil || range.upperBound > last!.upperBound
322	                    || (range.upperBound == last!.upperBound && range.lowerBound < last!.lowerBound) {
323	                    last = range
324	                }
325	            }
326	        }
327	        guard let cue = last, keys.count - cue.upperBound <= maxTokensAfterCue else { return false }
328	        return covered[..<cue.lowerBound].contains(false) // something was said to be corrected
329	    }
330	
331	    /// The run is immediately repeated (or was just said): "can we, can we move".
332	    /// Fillers inside the run are ignored ("can we, um, can we").
333	    static func isRepeat(_ run: [Int], input: [Token], a: [Int]) -> Bool {
334	        let keys = run.map { input[a[$0]].key }.filter { !fillers.contains($0) }
335	        guard !keys.isEmpty else { return false }
336	        let after = run.last! + 1
337	        if after + keys.count <= a.count,
338	           (after..<after + keys.count).map({ input[a[$0]].key }) == keys { return true }
339	        let before = run.first! - keys.count
340	        if before >= 0, (before..<run.first!).map({ input[a[$0]].key }) == keys { return true }
341	        return false
342	    }
343	
344	    /// Commas on both sides: "It's, I mean, fine" drops "I mean"; an opening
345	    /// "I mean, it works" keeps it.
346	    static func isBracketedFiller(_ run: [Int], keys: [String], input: [Token], a: [Int]) -> Bool {
347	        guard bracketedFillers.contains(keys), input[a[run.last!]].surface.hasSuffix(",") else { return false }
348	        let first = run.first!
349	        return first > 0 && input[a[first - 1]].surface.hasSuffix(",")
350	    }
351	
352	    /// The span of `deleted` the model's `inserted` words may replace: the same
353	    /// letters re-spaced, or a vocabulary term resembling the span.
354	    static func bestSubstitution(_ deleted: [Token], _ inserted: [Token],
355	                                 vocabularyKeys: Set<String>) -> Range<Int>? {
356	        guard !deleted.isEmpty, inserted.count <= maxSubstitutionTokens else { return nil }
357	        let target = inserted.map(\.key).joined()
358	        let isTerm = vocabularyKeys.contains(target)
359	        var best: (range: Range<Int>, score: Double)?
360	        for start in deleted.indices {
361	            for length in 1...min(maxSubstitutionTokens, deleted.count - start) {
362	                let span = deleted[start..<start + length].map(\.key).joined()
363	                let score: Double
364	                if span == target {
365	                    score = 2 // identical letters beat any resemblance
366	                } else if isTerm {
367	                    score = similarity(span, target)
368	                    guard score >= minVocabularySimilarity else { continue }
369	                } else {
370	                    continue
371	                }
372	                if best == nil || score > best!.score { best = (start..<start + length, score) }
373	            }
374	        }
375	        return best?.range
376	    }
377	
378	    /// 1 − (character edit distance ÷ longer length).
379	    static func similarity(_ s: String, _ t: String) -> Double {
380	        let x = Array(s), y = Array(t)
381	        guard !x.isEmpty, !y.isEmpty else { return x.isEmpty && y.isEmpty ? 1 : 0 }
382	        var prev = Array(0...y.count)
383	        for i in 1...x.count {
384	            var cur = [i] + Array(repeating: 0, count: y.count)
385	            for j in 1...y.count {
386	                cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x[i - 1] == y[j - 1] ? 0 : 1))
387	            }
388	            prev = cur
389	        }
390	        return 1 - Double(prev[y.count]) / Double(max(x.count, y.count))
391	    }
392	
393	    // MARK: helpers
394	
395	    private static func lastWordIndex(_ input: [Token], from start: Int, before end: Int) -> Int? {
396	        var i = end - 1
397	        while i >= start {
398	            if !input[i].key.isEmpty { return i }
399	            i -= 1
400	        }
401	        return nil
402	    }
403	
404	    static func trailingPunctuation(_ s: String) -> String {
405	        String(s.reversed().prefix { !$0.isLetter && !$0.isNumber }.reversed())
406	    }
407	
408	    static func stripTrailingPunctuation(_ s: String) -> String {
409	        String(s.dropLast(trailingPunctuation(s).count))
410	    }
411	
412	    private static func endsSentence(_ s: String) -> Bool {
413	        trailingPunctuation(s).contains { ".?!".contains($0) }
414	    }
415	
416	    private static func startsUppercase(_ s: String) -> Bool {
417	        s.first(where: \.isLetter)?.isUppercase ?? false
418	    }
419	
420	    /// Capitalizes an all-lowercase ordinary word opening a sentence; leaves
421	    /// vocabulary terms ("kubectl") and mixed-case words ("iPhone") alone.
422	    static func sentenceCased(_ s: String, _ vocabularyKeys: Set<String>) -> String {
423	        guard let idx = s.firstIndex(where: \.isLetter), !s.contains(where: \.isUppercase),
424	              !vocabularyKeys.contains(TranscriptCorrector.key(s)) else { return s }
425	        return s.replacingCharacters(in: idx...idx, with: s[idx].uppercased())
426	    }
427	}
