import Foundation

/// Holds the cleanup LLM to the edits dictation cleanup exists for. The
/// model's output is aligned word by word against the transcript it was
/// given, and only these edits survive:
///  - deleting filler sounds (um, uh, er, hmm, …), and "you know" / "I mean" /
///    "like" when the transcript sets them off with commas;
///  - deleting stutters (a word or phrase said twice back to back);
///  - deleting a self-corrected span that ends in a correction cue
///    ("at 2, no wait, 3" → "at 3"; "to Bob, sorry, I mean to Alice" → "to Alice");
///  - re-spacing or re-hyphenating the same letters ("fine tune" → "fine-tune");
///  - replacing a short span with a vocabulary term it resembles ("pie torch" → "PyTorch").
/// Every other change (a dropped clause, a paraphrase, an added word, an
/// answer to a dictated question) is reverted to the transcript's own words,
/// so the speaker's sentences come through as spoken. Measured on a 44-case
/// fidelity corpus, unguarded Llama-3.2-3B rewrote 10 of 22 sentences that
/// needed no edit (36 words lost), answered "Tell me a joke about databases"
/// with a joke, and obeyed a dictated "reply with the word banana".
///
/// Pure and deterministic; the output is exactly the model's text whenever
/// the model made only allowed edits.
public enum CleanupGuard {
    static let fillers: Set<String> = [
        "um", "umm", "uh", "uhh", "uhm", "er", "erm", "ah", "eh", "hmm", "hm", "mm", "mmm", "mhm",
    ]
    /// Deletable only when the transcript brackets them with commas on both
    /// sides ("I was, you know, thinking"): otherwise they are usually content.
    static let bracketedFillers: [[String]] = [["you", "know"], ["i", "mean"], ["like"]]
    /// A deleted run counts as a self-correction only if it ends in one of
    /// these (plus at most `maxTokensAfterCue` words) and has words before it.
    static let correctionCues: [[String]] = [
        ["no", "wait"], ["wait"], ["sorry"], ["i", "mean"], ["i", "meant"], ["actually"],
        ["make", "that"], ["scratch", "that"], ["or", "rather"], ["rather"], ["correction"], ["no"],
    ]
    /// Alignment is O(n·m): ~2,000 words a side (13+ minutes of speech, past
    /// `maxRecordSeconds`) before the guard stops aligning and keeps the
    /// transcript as spoken.
    static let maxAlignmentCells = 4_000_000
    static let maxCorrectionRun = 12
    static let maxTokensAfterCue = 2
    static let maxSubstitutionTokens = 4
    /// Letter similarity a span needs to be swapped for a vocabulary term:
    /// low enough for phonetic misses ("pie torch" → PyTorch, 0.75), high
    /// enough to refuse unrelated words.
    static let minVocabularySimilarity = 0.5
    /// Number words align with digits, so a correction the model wrote as
    /// "3 pm" still lines up with a spoken "three pm".
    static let numberWords: [String: String] = [
        "zero": "0", "one": "1", "two": "2", "three": "3", "four": "4", "five": "5",
        "six": "6", "seven": "7", "eight": "8", "nine": "9", "ten": "10", "eleven": "11",
        "twelve": "12", "thirteen": "13", "fourteen": "14", "fifteen": "15", "sixteen": "16",
        "seventeen": "17", "eighteen": "18", "nineteen": "19", "twenty": "20", "thirty": "30",
        "forty": "40", "fifty": "50", "sixty": "60", "seventy": "70", "eighty": "80", "ninety": "90",
    ]

    /// Lookup keys for `reconcile`'s vocabulary check; build once per term list.
    public static func vocabularyKeys(_ terms: [String]) -> Set<String> {
        Set(VocabularyPrompt.normalize(terms).map(TranscriptCorrector.key))
    }

    /// `vocabularyKeys` comes from `vocabularyKeys(_:)`.
    public static func reconcile(transcript: String, cleaned: String,
                                 vocabularyKeys: Set<String>) -> String {
        let input = tokenize(transcript)
        let output = tokenize(cleaned)
        let a = input.indices.filter { !input[$0].key.isEmpty }
        let b = output.indices.filter { !output[$0].key.isEmpty }
        guard !a.isEmpty, !b.isEmpty, a.count * b.count <= maxAlignmentCells else { return transcript }

        // 1. Decide the fate of every word in the transcript.
        var fate = [Fate](repeating: .restored, count: input.count)
        var revertedBoundary = Set<Int>() // input indices next to a dropped insertion
        var reverted = false
        let ops = align(a.map { input[$0].matchKey }, b.map { output[$0].matchKey })
        var k = 0
        var lastMatched = -1 // position in `a` of the latest aligned word
        while k < ops.count {
            if case .match(let ai, let bi) = ops[k] {
                fate[a[ai]] = .matched(b[bi])
                lastMatched = ai
                k += 1
                continue
            }
            var deleted: [Int] = [] // positions in `a`
            var inserted: [Int] = [] // positions in `b`
            while k < ops.count {
                if case .delete(let ai) = ops[k] { deleted.append(ai) } else if case .insert(let bi) = ops[k] {
                    inserted.append(bi)
                } else { break }
                k += 1
            }
            let matchAfter = k < ops.count
            let substitution = inserted.isEmpty ? nil
                : bestSubstitution(deleted.map { input[a[$0]] }, inserted.map { output[b[$0]] },
                                   vocabularyKeys: vocabularyKeys)
            if let s = substitution {
                let span = deleted[s]
                let surfaces = inserted.map { output[b[$0]].surface }
                fate[a[span[span.startIndex]]] = .substitutedHead(surfaces, last: a[span[span.endIndex - 1]])
                for ai in span.dropFirst() { fate[a[ai]] = .substitutedTail }
                judgeDeletion(Array(deleted[..<s.lowerBound]), keptAfter: true,
                              input: input, a: a, fate: &fate)
                judgeDeletion(Array(deleted[s.upperBound...]), keptAfter: matchAfter,
                              input: input, a: a, fate: &fate)
            } else {
                judgeDeletion(deleted, keptAfter: matchAfter, input: input, a: a, fate: &fate)
                if !inserted.isEmpty {
                    // Dropped model words: the aligned words on both sides of
                    // the gap were written around them.
                    reverted = true
                    if lastMatched >= 0 { revertedBoundary.insert(a[lastMatched]) }
                    let after = lastMatched + deleted.count + 1
                    if after < a.count { revertedBoundary.insert(a[after]) }
                }
            }
        }
        if a.contains(where: { if case .restored = fate[$0] { return true } else { return false } }) {
            reverted = true
        }
        // The model made only allowed edits: its text stands exactly as written.
        guard reverted else { return cleaned }

        // 2. Rebuild from the transcript. Words beside a reverted edit take the
        // transcript's spelling and punctuation: the model's there was written
        // for a sentence that no longer exists ("…to Thursday." before a
        // restored "because…" clause).
        var pieces: [Piece] = []
        var pendingDeletion: Int?  // first index of the deletion run awaiting its neighbor
        var lastWasKept = false
        for i in input.indices {
            switch fate[i] {
            case .matched(let bi):
                pieces.append(Piece(surface: output[bi].surface, first: i, input: i, kind: .matched,
                                    deletedBefore: pendingDeletion))
            case .restored:
                if input[i].key.isEmpty {
                    guard lastWasKept else { continue } // dangling punctuation of a deletion
                }
                pieces.append(Piece(surface: input[i].surface, first: i, input: i, kind: .restored,
                                    deletedBefore: pendingDeletion))
            case .substitutedHead(let surfaces, let last):
                pieces.append(Piece(surface: surfaces.joined(separator: " "), first: i, input: last,
                                    kind: .substituted, deletedBefore: pendingDeletion))
            case .substitutedTail:
                continue
            case .deleted:
                if pendingDeletion == nil { pendingDeletion = i }
                lastWasKept = false
                continue
            }
            pendingDeletion = nil
            lastWasKept = true
        }
        let trailingDeletion = pendingDeletion
        guard !pieces.isEmpty else { return transcript }

        func usesTranscriptSurface(_ p: Int) -> Bool {
            switch pieces[p].kind {
            case .restored: return true
            case .substituted: return false
            case .matched:
                if revertedBoundary.contains(pieces[p].input) { return true }
                if p > 0, pieces[p - 1].kind == .restored { return true }
                if p + 1 < pieces.count, pieces[p + 1].kind == .restored { return true }
                return false
            }
        }
        var surfaces: [String] = []
        var transcriptSurface: [Bool] = []
        for p in pieces.indices {
            let own = usesTranscriptSurface(p)
            transcriptSurface.append(own)
            switch pieces[p].kind {
            case .matched where own:
                surfaces.append(input[pieces[p].input].surface)
            case .substituted where p + 1 < pieces.count && pieces[p + 1].kind == .restored:
                // Keep the transcript's punctuation after a swapped-in term.
                surfaces.append(stripTrailingPunctuation(pieces[p].surface)
                                + trailingPunctuation(input[pieces[p].input].surface))
            default:
                surfaces.append(pieces[p].surface)
            }
        }

        // 3. Seam repair where an allowed deletion meets transcript-spelled words.
        for p in pieces.indices {
            guard let start = pieces[p].deletedBefore else { continue }
            let lastDeleted = lastWordIndex(input, from: start, before: pieces[p].first)
            if p > 0, transcriptSurface[p - 1], surfaces[p - 1].hasSuffix(","),
               let last = lastDeleted, input[last].surface.hasSuffix(",") {
                surfaces[p - 1].removeLast() // "which is, um, way" → "which is way"
            }
            let atSentenceStart = p == 0 || endsSentence(surfaces[p - 1])
            if atSentenceStart, transcriptSurface[p], startsUppercase(input[start].surface) {
                surfaces[p] = sentenceCased(surfaces[p], vocabularyKeys) // "Hmm, let me" → "Let me"
            }
        }
        // The model capitalized the opening word: keep that even where the
        // transcript's own (lowercase) first word came back.
        if transcriptSurface[0], output[b[0]].surface.first(where: \.isLetter)?.isUppercase == true {
            surfaces[0] = sentenceCased(surfaces[0], vocabularyKeys)
        }
        if let start = trailingDeletion, let lastIdx = surfaces.indices.last, transcriptSurface[lastIdx],
           !endsSentence(surfaces[lastIdx]),
           let last = lastWordIndex(input, from: start, before: input.count) {
            let terminal = trailingPunctuation(input[last].surface).filter { ".?!".contains($0) }
            if !terminal.isEmpty {
                surfaces[lastIdx] = stripTrailingPunctuation(surfaces[lastIdx]) + terminal // "I think, um." → "I think."
            }
        }
        return surfaces.joined(separator: " ")
    }

    // MARK: tokens and alignment

    struct Token {
        let surface: String
        let key: String      // letters+digits, lowercased; "" for punctuation-only
        let matchKey: String // key with number words as digits
    }

    static func tokenize(_ text: String) -> [Token] {
        text.split(whereSeparator: \.isWhitespace).map { raw in
            let surface = String(raw)
            let key = TranscriptCorrector.key(surface)
            return Token(surface: surface, key: key, matchKey: numberWords[key] ?? key)
        }
    }

    enum Op: Equatable { case match(Int, Int), delete(Int), insert(Int) }

    /// Longest-common-subsequence alignment, backtracked from the END so a
    /// repeated word pairs with its LAST occurrence: the kept half of a
    /// stutter or a self-correction is the one spoken later.
    static func align(_ x: [String], _ y: [String]) -> [Op] {
        let n = x.count, m = y.count
        let width = m + 1
        var dp = [Int32](repeating: 0, count: (n + 1) * width)
        for i in stride(from: 1, through: n, by: 1) {
            for j in stride(from: 1, through: m, by: 1) {
                dp[i * width + j] = x[i - 1] == y[j - 1]
                    ? dp[(i - 1) * width + j - 1] + 1
                    : max(dp[(i - 1) * width + j], dp[i * width + j - 1])
            }
        }
        var ops: [Op] = []
        var i = n, j = m
        while i > 0 || j > 0 {
            if i > 0, j > 0, x[i - 1] == y[j - 1] {
                ops.append(.match(i - 1, j - 1)); i -= 1; j -= 1
            } else if i > 0, j == 0 || dp[(i - 1) * width + j] >= dp[i * width + j - 1] {
                ops.append(.delete(i - 1)); i -= 1
            } else {
                ops.append(.insert(j - 1)); j -= 1
            }
        }
        return ops.reversed()
    }

    // MARK: edit rules

    enum Fate {
        case matched(Int)            // output token index
        case restored                // transcript word the model dropped without cause
        case deleted                 // an allowed deletion
        case substitutedHead([String], last: Int) // output surfaces; last transcript index
        case substitutedTail
    }

    enum PieceKind { case matched, restored, substituted }

    struct Piece {
        let surface: String
        let first: Int          // first transcript index covered
        let input: Int          // last transcript index covered
        let kind: PieceKind
        let deletedBefore: Int? // start of an allowed deletion right before this piece
    }

    /// Marks the allowed deletions in a run of dropped transcript words
    /// (positions in `a`); everything else stays `.restored`.
    static func judgeDeletion(_ run: [Int], keptAfter: Bool, input: [Token], a: [Int],
                              fate: inout [Fate]) {
        guard !run.isEmpty else { return }
        let keys = run.map { input[a[$0]].key }
        let wholeRun = isCorrection(keys, keptAfter: keptAfter)
            || isRepeat(run, input: input, a: a)
            || isBracketedFiller(run, keys: keys, input: input, a: a)
        for (offset, ai) in run.enumerated() {
            let key = keys[offset]
            if wholeRun || fillers.contains(key) || isStutter(ai, run: run, input: input, a: a) {
                fate[a[ai]] = .deleted
            }
        }
    }

    /// The same word said again right beside it, fillers aside ("the, uh, the
    /// link"), where that other copy is outside this run: dropping both copies
    /// would lose the word.
    static func isStutter(_ ai: Int, run: [Int], input: [Token], a: [Int]) -> Bool {
        let key = input[a[ai]].key
        for step in [-1, 1] {
            var j = ai + step
            while j >= 0, j < a.count, fillers.contains(input[a[j]].key) { j += step }
            if j >= 0, j < a.count, !run.contains(j), input[a[j]].key == key { return true }
        }
        return false
    }

    /// "<words> <cue> [≤2 words]" with a replacement still to come: the
    /// corrected words, then the cue, e.g. "2, no wait," or "Bob, sorry, I mean".
    static func isCorrection(_ keys: [String], keptAfter: Bool) -> Bool {
        guard keptAfter, keys.count >= 2, keys.count <= maxCorrectionRun else { return false }
        var covered = [Bool](repeating: false, count: keys.count)
        var last: Range<Int>? // the cue ending latest (longest on ties)
        for start in keys.indices {
            for cue in correctionCues where start + cue.count <= keys.count
                && Array(keys[start..<start + cue.count]) == cue {
                for i in start..<start + cue.count { covered[i] = true }
                let range = start..<start + cue.count
                if last == nil || range.upperBound > last!.upperBound
                    || (range.upperBound == last!.upperBound && range.lowerBound < last!.lowerBound) {
                    last = range
                }
            }
        }
        guard let cue = last, keys.count - cue.upperBound <= maxTokensAfterCue else { return false }
        return covered[..<cue.lowerBound].contains(false) // something was said to be corrected
    }

    /// The run is immediately repeated (or was just said): "can we, can we move".
    /// Fillers inside the run are ignored ("can we, um, can we").
    static func isRepeat(_ run: [Int], input: [Token], a: [Int]) -> Bool {
        let keys = run.map { input[a[$0]].key }.filter { !fillers.contains($0) }
        guard !keys.isEmpty else { return false }
        let after = run.last! + 1
        if after + keys.count <= a.count,
           (after..<after + keys.count).map({ input[a[$0]].key }) == keys { return true }
        let before = run.first! - keys.count
        if before >= 0, (before..<run.first!).map({ input[a[$0]].key }) == keys { return true }
        return false
    }

    /// Commas on both sides: "It's, I mean, fine" drops "I mean"; an opening
    /// "I mean, it works" keeps it.
    static func isBracketedFiller(_ run: [Int], keys: [String], input: [Token], a: [Int]) -> Bool {
        guard bracketedFillers.contains(keys), input[a[run.last!]].surface.hasSuffix(",") else { return false }
        let first = run.first!
        return first > 0 && input[a[first - 1]].surface.hasSuffix(",")
    }

    /// The span of `deleted` the model's `inserted` words may replace: the same
    /// letters re-spaced, or a vocabulary term resembling the span.
    static func bestSubstitution(_ deleted: [Token], _ inserted: [Token],
                                 vocabularyKeys: Set<String>) -> Range<Int>? {
        guard !deleted.isEmpty, inserted.count <= maxSubstitutionTokens else { return nil }
        let target = inserted.map(\.key).joined()
        let isTerm = vocabularyKeys.contains(target)
        var best: (range: Range<Int>, score: Double)?
        for start in deleted.indices {
            for length in 1...min(maxSubstitutionTokens, deleted.count - start) {
                let span = deleted[start..<start + length].map(\.key).joined()
                let score: Double
                if span == target {
                    score = 2 // identical letters beat any resemblance
                } else if isTerm {
                    score = similarity(span, target)
                    guard score >= minVocabularySimilarity else { continue }
                } else {
                    continue
                }
                if best == nil || score > best!.score { best = (start..<start + length, score) }
            }
        }
        return best?.range
    }

    /// 1 − (character edit distance ÷ longer length).
    static func similarity(_ s: String, _ t: String) -> Double {
        let x = Array(s), y = Array(t)
        guard !x.isEmpty, !y.isEmpty else { return x.isEmpty && y.isEmpty ? 1 : 0 }
        var prev = Array(0...y.count)
        for i in 1...x.count {
            var cur = [i] + Array(repeating: 0, count: y.count)
            for j in 1...y.count {
                cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x[i - 1] == y[j - 1] ? 0 : 1))
            }
            prev = cur
        }
        return 1 - Double(prev[y.count]) / Double(max(x.count, y.count))
    }

    // MARK: helpers

    private static func lastWordIndex(_ input: [Token], from start: Int, before end: Int) -> Int? {
        var i = end - 1
        while i >= start {
            if !input[i].key.isEmpty { return i }
            i -= 1
        }
        return nil
    }

    static func trailingPunctuation(_ s: String) -> String {
        String(s.reversed().prefix { !$0.isLetter && !$0.isNumber }.reversed())
    }

    static func stripTrailingPunctuation(_ s: String) -> String {
        String(s.dropLast(trailingPunctuation(s).count))
    }

    private static func endsSentence(_ s: String) -> Bool {
        trailingPunctuation(s).contains { ".?!".contains($0) }
    }

    private static func startsUppercase(_ s: String) -> Bool {
        s.first(where: \.isLetter)?.isUppercase ?? false
    }

    /// Capitalizes an all-lowercase ordinary word opening a sentence; leaves
    /// vocabulary terms ("kubectl") and mixed-case words ("iPhone") alone.
    static func sentenceCased(_ s: String, _ vocabularyKeys: Set<String>) -> String {
        guard let idx = s.firstIndex(where: \.isLetter), !s.contains(where: \.isUppercase),
              !vocabularyKeys.contains(TranscriptCorrector.key(s)) else { return s }
        return s.replacingCharacters(in: idx...idx, with: s[idx].uppercased())
    }
}

