import Foundation
@testable import MurmurKit

// Usage: Probe cases.json  -> JSON array of {"t":..., "c":..., "v":[...], "e": expected?}
struct Case: Decodable { let t: String; let c: String; let v: [String]?; let e: String?; let n: String? }

let args = CommandLine.arguments
let path = args.count > 1 ? args[1] : "cases.json"
let debug = args.contains("--debug")
let data = try! Data(contentsOf: URL(fileURLWithPath: path))
let cases = try! JSONDecoder().decode([Case].self, from: data)
for (i, c) in cases.enumerated() {
    let keys = CleanupGuard.vocabularyKeys(c.v ?? [])
    let started = Date()
    let out = CleanupGuard.reconcile(transcript: c.t, cleaned: c.c, vocabularyKeys: keys)
    let ms = -started.timeIntervalSinceNow * 1000
    let tag = c.e == nil ? "    " : (c.e == out ? "OK  " : "DIFF")
    print("[\(i)] \(tag) \(c.n ?? "")")
    if c.t.count < 400 {
        print("   T: \(c.t)")
        print("   C: \(c.c)")
        if let v = c.v, !v.isEmpty { print("   V: \(v)") }
        print("   O: \(out)")
        if let e = c.e, e != out { print("   E: \(e)") }
    } else {
        print("   T.len=\(c.t.count) C.len=\(c.c.count) O.len=\(out.count) O==T:\(out == c.t) O==C:\(out == c.c)")
    }
    print(String(format: "   %.1f ms", ms))
    if debug {
        let input = CleanupGuard.tokenize(c.t), output = CleanupGuard.tokenize(c.c)
        let a = input.indices.filter { !input[$0].key.isEmpty }
        let b = output.indices.filter { !output[$0].key.isEmpty }
        let ops = CleanupGuard.align(a.map { input[$0].matchKey }, b.map { output[$0].matchKey })
        var line = "   ops:"
        for op in ops {
            switch op {
            case .match(let x, let y): line += " =\(input[a[x]].surface)|\(output[b[y]].surface)"
            case .delete(let x): line += " -\(input[a[x]].surface)"
            case .insert(let y): line += " +\(output[b[y]].surface)"
            }
        }
        print(line)
    }
}
EOF
