import Foundation
@testable import MurmurKit

struct LCG { var s: UInt64; mutating func next() -> UInt64 { s = s &* 6364136223846793005 &+ 1442695040888963407; return s >> 33 }
    mutating func int(_ n: Int) -> Int { Int(next() % UInt64(n)) }
    mutating func chance(_ p: Double) -> Bool { Double(next() % 10000) / 10000 < p } }

let content = ["apple","bravo","cedar","delta","ember","falcon","garnet","harbor","indigo","juniper","kettle","lumen",
               "maple","nectar","orbit","pepper","quartz","raven","sierra","timber","umber","velvet","willow","xenon",
               "yonder","zephyr","anchor","basil","canyon","dagger","eagle","fable"]
let fillersList = ["um","uh","er","hmm","erm","uhm","mm"]
let junk = ["zqa","zqb","zqc","zqd","zqe","banana","paris","sure","okay"]
let key = { (s: String) in TranscriptCorrector.key(s) }

struct Tok { var s: String; var kind: Int; var group: Int } // kind 0 content,1 filler,2 punct
var rng = LCG(s: UInt64(CommandLine.arguments.count > 1 ? Int(CommandLine.arguments[1])! : 42))
let iterations = CommandLine.arguments.count > 2 ? Int(CommandLine.arguments[2])! : 20000
var violations: [String: (Int, String)] = [:]
func report(_ kind: String, _ msg: String) { if violations[kind] == nil { violations[kind] = (1, msg) } else { violations[kind]!.0 += 1 } }

for _ in 0..<iterations {
    // Transcript: unique content words, occasional stutters, fillers, punctuation.
    var toks: [Tok] = []
    var pool = content.shuffled(using: &SystemRandomNumberGenerator.shared)
    let n = 3 + rng.int(10)
    var g = 0
    for _ in 0..<n {
        guard let w = pool.popLast() else { break }
        if rng.chance(0.15) { toks.append(Tok(s: fillersList[rng.int(fillersList.count)] + (rng.chance(0.5) ? "," : ""), kind: 1, group: -1)) }
        if rng.chance(0.07) { toks.append(Tok(s: "-", kind: 2, group: -1)) }
        let copies = rng.chance(0.15) ? 2 + rng.int(2) : 1
        for c in 0..<copies {
            var s = w
            if c < copies - 1 && rng.chance(0.4) { s += "," }
            toks.append(Tok(s: s, kind: 0, group: g))
            if c < copies - 1 && rng.chance(0.2) { toks.append(Tok(s: fillersList[rng.int(fillersList.count)] + ",", kind: 1, group: -1)) }
        }
        g += 1
        if rng.chance(0.15), toks.last!.kind == 0 { toks[toks.count - 1].s += [".", "?", "!"][rng.int(3)] }
    }
    let transcript = toks.map(\.s).joined(separator: " ")
    // Model output: random edits.
    var out = toks
    var onlyAllowed = true
    let edits = rng.int(4)
    for _ in 0..<edits {
        guard !out.isEmpty else { break }
        let i = rng.int(out.count)
        switch rng.int(7) {
        case 0: // delete a filler or a stutter copy (allowed) if possible, else any
            if out[i].kind == 1 { out.remove(at: i) }
            else if out[i].kind == 0, out.filter({ $0.group == out[i].group }).count > 1 { out.remove(at: i) }
            else { onlyAllowed = false; out.remove(at: i) }
        case 1: onlyAllowed = false; out.insert(Tok(s: junk[rng.int(junk.count)], kind: 3, group: -2), at: i)
        case 2: if i + 1 < out.count, key(out[i].s) != key(out[i + 1].s) { onlyAllowed = false; out.swapAt(i, i + 1) }
        case 3: out[i].s = out[i].s.capitalized
        case 4: out[i].s += [",", ".", ";", ""][rng.int(4)]
        case 5: onlyAllowed = false; out[i] = Tok(s: junk[rng.int(junk.count)], kind: 3, group: -2)
        default: out[i].s = out[i].s.trimmingCharacters(in: .punctuationCharacters)
        }
    }
    if out.isEmpty { continue }
    let cleaned = out.map(\.s).filter { !$0.isEmpty }.joined(separator: " ")
    let result = CleanupGuard.reconcile(transcript: transcript, cleaned: cleaned, vocabularyKeys: [])
    let outKeys = result.split(whereSeparator: \.isWhitespace).map { key(String($0)) }.filter { !$0.isEmpty }
    let desc = "T=\(transcript) | C=\(cleaned) | O=\(result)"
    // I2: no junk
    let junkKeys = Set(junk)
    let transcriptKeys = Set(toks.map { key($0.s) })
    if outKeys.contains(where: { junkKeys.contains($0) && !transcriptKeys.contains($0) }) { report("junk pasted", desc) }
    // I3/I4: every content group survives at least once
    for grp in 0..<g {
        guard let w = toks.first(where: { $0.group == grp }) else { continue }
        let k = key(w.s)
        if !outKeys.contains(k) { report("content word lost", desc) }
    }
    // Extra copies: output should not contain more copies than transcript
    for grp in 0..<g {
        guard let w = toks.first(where: { $0.group == grp }) else { continue }
        let k = key(w.s)
        let inCount = toks.filter { $0.group == grp }.count
        if outKeys.filter({ $0 == k }).count > inCount { report("word duplicated", desc) }
    }
    // I5: only allowed edits -> exact model text
    if onlyAllowed, result != cleaned { report("allowed-only not byte-for-byte", desc) }
    // cosmetics
    if result.contains(",,") || result.contains(", ,") || result.contains(" ,") && !transcript.contains(" ,") { report("comma artifact", desc) }
}
for (k, v) in violations.sorted(by: { $0.key < $1.key }) { print("\(k): \(v.0)\n   e.g. \(v.1)") }
print("done \(iterations)")
EOF
